// Normalize inbound fields (including competitors, overview, website) into a clean, consistent payload.

const input = $json || {};

const toStr = (v) => (v == null ? '' : String(v).trim());
const firstNonEmpty = (...keys) => {
  for (const k of keys) {
    const v = toStr(input[k]);
    if (v) return v;
  }
  return '';
};

// Basic URL scrubber: trim + ensure http(s) + collapse double slashes
const cleanUrl = (raw) => {
  let u = toStr(raw);
  if (!u) return '';
  u = u.replace(/^['"\s]+|['"\s]+$/g, '');
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
  u = u.replace(/^(https?:\/\/)(\/)+/i, '$1');
  return u;
};

// Canonical base fields
const clientId     = firstNonEmpty('clientId', 'client_id', 'id');
const sheetDocId   = firstNonEmpty('sheetDocId', 'sheet_id', 'sheetId');
const writeKey     = firstNonEmpty('writeKey', 'write_key');
const isTest       = input.isTest === true || String(input.isTest).toLowerCase() === 'true';

const facebookUrl  = cleanUrl(firstNonEmpty('facebook_profile_url', 'facebook_url', 'Facebook_url', 'facebookUrl'));
const instagramUrl = cleanUrl(firstNonEmpty('instagram_profile_url', 'instagram_url', 'ig_url', 'instagramUrl'));

const website      = cleanUrl(firstNonEmpty('website', 'site', 'homepage'));
const overview     = firstNonEmpty('overview', 'bio', 'description');

// Competitors normalization
const rawCompetitors = Array.isArray(input.competitors) ? input.competitors : [];
const competitors = rawCompetitors
  .map((c) => {
    const name = toStr(c?.name);
    const site = cleanUrl(c?.website || c?.site || '');
    const ig   = cleanUrl(c?.instagram_url || c?.instagramUrl || c?.ig_url || '');
    return { name, website: site, instagramUrl: ig };
  })
  // Keep rows that have at least a name AND a plausible IG URL
  .filter((c) => c.name && c.instagramUrl);

// Meta
const workflowVersion = '2025-10-08.keyword-research.v2';
const runId = `${new Date().toISOString()}|keyword-research|${clientId || 'noClient'}`;

return [
  {
    json: {
      clientId,
      sheetDocId,
      writeKey,
      isTest,
      facebookUrl,
      instagramUrl,
      website,
      overview,
      competitors,      // normalized list: [{ name, website, instagramUrl }]
      workflowVersion,
      runId,
      receivedAt: new Date().toISOString()
    }
  }
];

// Validate required inputs + shape of competitors.
// Required: sheetDocId, instagramUrl, facebookUrl
// Optional but recommended: website, overview, competitors[]

const j = $json || {};
const missing = [];
const warnings = [];

const need = (key, label = key) => {
  const v = j[key];
  if (!v || String(v).trim() === '') missing.push(label);
};

need('sheetDocId', 'sheetDocId');

if (missing.length) {
  throw new Error(`Missing required inputs: ${missing.join(', ')}`);
}

// URL sanity
if (j.facebookUrl && !/https?:\/\/(www\.)?facebook\.com\//i.test(j.facebookUrl)) {
  warnings.push(`facebookUrl does not look like a Facebook link: ${j.facebookUrl}`);
}
if (j.instagramUrl && !/https?:\/\/(www\.)?instagram\.com\//i.test(j.instagramUrl)) {
  warnings.push(`instagramUrl does not look like an Instagram link: ${j.instagramUrl}`);
}
if (j.website && !/^https?:\/\//i.test(j.website)) {
  warnings.push(`website is not a valid URL: ${j.website}`);
}

// Competitors shape checks (optional but helpful)
if (Array.isArray(j.competitors)) {
  const tooMany = j.competitors.length > 12;
  if (tooMany) warnings.push(`competitors list is long (${j.competitors.length}); consider capping at ~8–12 for cost/speed.`);

  const bad = [];
  j.competitors.forEach((c, idx) => {
    const nameOk = !!(c && c.name && String(c.name).trim());
    const igOk   = !!(c && c.instagramUrl && /instagram\.com\//i.test(c.instagramUrl));
    if (!nameOk || !igOk) bad.push(idx);
  });
  if (bad.length) {
    warnings.push(`Some competitors missing name or instagramUrl at indices: ${bad.join(', ')}`);
  }
} else if (j.competitors != null) {
  warnings.push('competitors provided but not an array; ignoring.');
}

// Soft checks on overview
if (j.overview && j.overview.length < 40) {
  warnings.push('overview appears very short; richer context improves trend quality.');
}

return [
  {
    json: {
      ...j,
      validationTimestamp: new Date().toISOString(),
      validationWarnings: warnings
    }
  }
];

// Robustly parse Perplexity/OpenAI response, tolerate object or JSON-string content,
// normalize slugs, and enforce 10 items.

const base = $item(0).$node['Validate Inputs']?.json ?? {};
const first = $input.first()?.json ?? {};

// --- Safely unwrap model content into string OR object ---
function pickPayload(value) {
  if (value == null) return null;

  // Plain JSON string / text response
  if (typeof value === 'string') return value;

  // Already parsed JSON object
  if (typeof value === 'object' && !Array.isArray(value)) {
    // If this object itself looks like the target payload, return it
    if (value.platform || value.items) return value;

    // Common nested fields
    if ('text' in value) {
      const v = pickPayload(value.text);
      if (v != null && v !== '') return v;
    }

    if ('content' in value) {
      const v = pickPayload(value.content);
      if (v != null && v !== '') return v;
    }

    if ('message' in value) {
      const v = pickPayload(value.message);
      if (v != null && v !== '') return v;
    }

    if ('output' in value) {
      const v = pickPayload(value.output);
      if (v != null && v !== '') return v;
    }
  }

  // Arrays: return first usable payload
  if (Array.isArray(value)) {
    for (const item of value) {
      const v = pickPayload(item);
      if (v != null && v !== '') return v;
    }
  }

  return null;
}

const rawPayload =
  pickPayload(first?.output) ??
  pickPayload(first?.message) ??
  pickPayload(first?.content);

if (rawPayload == null || rawPayload === '') {
  throw new Error('IG trends response missing content');
}

// --- Extract JSON if payload is a string; otherwise use object directly ---
function extractJson(text) {
  let t = String(text || '').trim();

  const fenceRe = /```(?:json)?\s*([\s\S]*?)\s*```/i;
  const m = t.match(fenceRe);
  if (m && m[1]) t = m[1].trim();

  // If still not plain JSON, try grabbing a JSON-looking block
  if (!/^\s*[\[{]/.test(t)) {
    const firstObj = t.indexOf('{');
    const lastObj = t.lastIndexOf('}');
    const firstArr = t.indexOf('[');
    const lastArr = t.lastIndexOf(']');

    const objSpan = firstObj !== -1 && lastObj !== -1 && lastObj > firstObj;
    const arrSpan = firstArr !== -1 && lastArr !== -1 && lastArr > firstArr;

    if (objSpan && arrSpan) {
      t =
        firstObj < firstArr
          ? t.slice(firstObj, lastObj + 1)
          : t.slice(firstArr, lastArr + 1);
    } else if (objSpan) {
      t = t.slice(firstObj, lastObj + 1);
    } else if (arrSpan) {
      t = t.slice(firstArr, lastArr + 1);
    }
  }

  return JSON.parse(t);
}

let parsed;
try {
  parsed =
    typeof rawPayload === 'string'
      ? extractJson(rawPayload)
      : rawPayload;
} catch (err) {
  throw new Error(`IG trends response is not valid JSON: ${err.message}`);
}

// --- Validate platform ---
const platform = String(parsed?.platform || '').toLowerCase();
if (platform !== 'instagram') {
  throw new Error(
    `IG trends platform mismatch: expected "instagram", received "${parsed?.platform}"`
  );
}

// --- Normalize items ---
const items = Array.isArray(parsed?.items) ? parsed.items : [];
const cleaned = [];
const seen = new Set();
const warnings = [];

function normSlug(s) {
  let t = String(s || '').trim();
  t = t.replace(/^#/, '').toLowerCase();
  t = t.replace(/\s+/g, '');
  t = t.replace(/[^a-z0-9_]/g, '');
  return t;
}

function validIgLink(slug, link) {
  const want = `https://www.instagram.com/explore/tags/${encodeURIComponent(slug)}/`;
  const ok =
    typeof link === 'string' &&
    /^https?:\/\/(www\.)?instagram\.com\/explore\/tags\/[^/]+\/?$/i.test(link);
  return ok ? link : want;
}

for (const entry of items) {
  const trendRaw = entry?.trend ?? entry?.hashtag ?? '';
  const slug = normSlug(trendRaw);

  if (!slug) continue;

  if (slug.length < 2 || slug.length > 48) {
    warnings.push(`Trend "${trendRaw}" skipped due to length bounds`);
    continue;
  }

  if (seen.has(slug)) {
    warnings.push(`Duplicate trend skipped: ${slug}`);
    continue;
  }

  seen.add(slug);
  const link = validIgLink(slug, entry?.link);
  cleaned.push({ trend: slug, link });
}

// Enforce EXACTLY 10: truncate if >10; error if <10
if (cleaned.length > 10) cleaned.length = 10;

if (cleaned.length !== 10) {
  throw new Error(
    `IG trends validation failed: expected 10 items, received ${cleaned.length}`
  );
}

return [
  {
    json: {
      ...base,
      igTrends: cleaned,
      igTrendsRaw: parsed,
      igTrendWarnings: warnings,
      igParsedAt: new Date().toISOString(),
    },
  },
];

const base = $item(0).$node['Parse IG Trends']?.json ?? {};

// Support both old Chat Completions shape and new Responses API shape
const rawContent =
  $json?.choices?.[0]?.message?.content ??
  $json?.output?.[0]?.content?.find?.(c => c.type === 'output_text')?.text ??
  $json?.output?.[0]?.content?.[0]?.text ??
  '';

if (!rawContent) {
  throw new Error('FB trends response missing content');
}

function extractJson(text) {
  let t = String(text || '').trim();

  const fenceRe = /```(?:json)?\s*([\s\S]*?)\s*```/i;
  const m = t.match(fenceRe);
  if (m && m[1]) t = m[1].trim();

  if (!/^\s*[\[{]/.test(t)) {
    const first = t.indexOf('{');
    const last = t.lastIndexOf('}');
    if (first !== -1 && last !== -1 && last > first) {
      t = t.slice(first, last + 1);
    }
  }

  return JSON.parse(t);
}

let parsed;
try {
  parsed = extractJson(rawContent);
} catch (err) {
  throw new Error(`FB trends response is not valid JSON: ${err.message}`);
}

const platform = String(parsed.platform || '').toLowerCase();
if (platform !== 'facebook') {
  throw new Error(
    `FB trends platform mismatch: expected "facebook", received "${parsed.platform}"`
  );
}

const items = Array.isArray(parsed.items) ? parsed.items : [];
const cleaned = [];
const seen = new Set();
const warnings = [];

function normSlug(s) {
  let t = String(s || '').trim();
  t = t.replace(/^#/, '').toLowerCase();
  t = t.replace(/\s+/g, '');
  t = t.replace(/[^a-z0-9_]/g, '');
  return t;
}

function validFbLink(slug, link) {
  const want = `https://www.facebook.com/hashtag/${encodeURIComponent(slug)}`;
  const ok =
    typeof link === 'string' &&
    /^https?:\/\/(www\.)?facebook\.com\/hashtag\/[^/]+\/?$/i.test(link);

  return ok ? link.replace(/\/+$/, '') : want;
}

for (const entry of items) {
  const trendRaw = entry?.trend ?? entry?.hashtag ?? '';
  const slug = normSlug(trendRaw);
  if (!slug) continue;

  if (slug.length < 2 || slug.length > 48) {
    warnings.push(`Trend "${trendRaw}" skipped due to length bounds`);
    continue;
  }

  if (seen.has(slug)) {
    warnings.push(`Duplicate trend skipped: ${slug}`);
    continue;
  }

  seen.add(slug);
  const link = validFbLink(slug, entry?.link);
  cleaned.push({ trend: slug, link });
}

if (cleaned.length > 10) cleaned.length = 10;
if (cleaned.length !== 10) {
  throw new Error(
    `FB trends validation failed: expected 10 items, received ${cleaned.length}`
  );
}

// Return ONE item containing the fbTrends array
return [
  {
    json: {
      ...base,
      fbTrends: cleaned,
      fbTrendsRaw: parsed,
      fbTrendWarnings: warnings,
      fbParsedAt: new Date().toISOString(),
    },
  },
];

// Build 20 rows (10 IG + 10 FB) for the Market research sheet
// Columns: writeKey, Platform, Trend Description & Hashtags, Link
// Pass-through (not written as columns): sheetDocId, runId

const ig = Array.isArray($json.igTrends) ? $json.igTrends : [];
const fb = Array.isArray($json.fbTrends) ? $json.fbTrends : [];

if (ig.length !== 10) {
  throw new Error(`Expected 10 Instagram trends before writing rows, found ${ig.length}`);
}
if (fb.length !== 10) {
  throw new Error(`Expected 10 Facebook trends before writing rows, found ${fb.length}`);
}

const rows = [];
const sheetDocId = $json.sheetDocId;
const runId = $json.runId || '';
const writeKey = $json.writeKey || '';

const ensureIgLink = (slug, link) => {
  const want = `https://www.instagram.com/explore/tags/${encodeURIComponent(slug)}/`;
  const ok = typeof link === 'string' &&
             /^https?:\/\/(www\.)?instagram\.com\/explore\/tags\/[^/]+\/?$/i.test(link);
  return ok ? (link.endsWith('/') ? link : link + '/') : want;
};

const ensureFbLink = (slug, link) => {
  const want = `https://www.facebook.com/hashtag/${encodeURIComponent(slug)}`;
  const ok = typeof link === 'string' &&
             /^https?:\/\/(www\.)?facebook\.com\/hashtag\/[^/]+\/?$/i.test(link);
  // Prefer no trailing slash for FB
  return (ok ? link : want).replace(/\/+$/, '');
};

for (const entry of ig) {
  const slug = String(entry.trend || '').trim().toLowerCase();
  rows.push({
    writeKey,
    Platform: 'Instagram',
    'Trend Description & Hashtags': `#${slug}`,
    Link: ensureIgLink(slug, entry.link),
    // pass-through for the Sheets node config
    sheetDocId,
    runId
  });
}

for (const entry of fb) {
  const slug = String(entry.trend || '').trim().toLowerCase();
  rows.push({
    writeKey,
    Platform: 'Facebook',
    'Trend Description & Hashtags': `#${slug}`,
    Link: ensureFbLink(slug, entry.link),
    // pass-through for the Sheets node config
    sheetDocId,
    runId
  });
}

return rows.map(row => ({ json: row }))

